"""Build four remaining Turkey chapters from cited original editorial locators.

No imported prose, images, historical polygons or asserted migration/front routes.
Run from repository root. The urban series is a cached WDI subset, CC BY 4.0.
"""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'data/history/turkey'
def write(p,d):
 p.parent.mkdir(parents=True,exist_ok=True)
 p.write_text(json.dumps(d,ensure_ascii=False,indent=1)+'\n',encoding='utf-8')
U='https://whc.unesco.org/en/list/'
MET='https://www.metmuseum.org/essays/the-art-of-the-ottomans-before-1600'
SUL='https://www.metmuseum.org/essays/the-age-of-suleyman-the-magnificent-r-1520-1566'
PAR='https://www.tbmm.gov.tr/history/'
GER='https://www.auswaertiges-amt.de/de/aussenpolitik/anwerbeabkommen/2493338'
NATO='https://www.nato.int/cps/en/natohq/declassified_191048.htm'
EU='https://www.consilium.europa.eu/en/policies/turkiye/'
OHCHR='https://www.ohchr.org/Documents/Countries/TR/OHCHR_South-East_TurkeyReport_10March2017.pdf'
QUAKE='https://earthquake.usgs.gov/earthquakes/eventpage/us6000jllz/executive'
CY='https://unficyp.unmissions.org/en/events-summer-1974'
RET='https://www.unhcr.org/tr/en/news/press-releases/unhcr-historic-return-displaced-syrians-presents-opportunity-and-urgent'
WB='https://www.worldbank.org/en/country/turkey/publication/turkey-urbanization-review'
LOC={'Istanbul':[28.98,41.01],'Ankara':[32.85,39.93],'Bursa':[29.06,40.19],'Edirne':[26.56,41.68],'Iznik':[29.72,40.43],'Cairo':[31.24,30.04],'Baghdad':[44.36,33.32],'Izmir':[27.14,38.42],'Diyarbakir':[40.23,37.91],'Nusaybin':[41.22,37.07],'Bonn':[7.1,50.73],'Brussels':[4.35,50.85],'Aleppo':[37.16,36.2],'Gaziantep':[37.38,37.07],'Nicosia':[33.36,35.17]}
def point(name,at=None,color='c3'):
 return {'at':at or LOC[name],'label':name,'color':color,'r':5}
def scene(title,text,center,zoom,points=(),**kw):
 return {'title':title,'text':text,'view':{'mode':'globe','center':center,'zoom':zoom},'modernBorders':False,'layers':[], 'points':list(points),**kw}
def event(title,date,at,text,url,kind='history'):
 return {'title':title,'date':date,'at':at,'text':text,'url':url,'source':'Primary institutional reference; original Orbis annotation','kind':kind}
def build(id,title,hook,scenes,items,refs,asof,extra_data=None):
 name=id.removeprefix('tr-')
 data={'events':f'data/history/turkey/{name}.json',**(extra_data or {})}
 note='Original Orbis factual annotations, not copied source prose. Locations are approximate city/site locators, not surveyed footprints. Historical geometry fallback: cited located events and places; no empire, ethnic or control polygons are inferred. Source coverage ends '+asof+'. Editorial cutoff: 14 October 2026. References by scene: '+ ' ; '.join(refs)
 write(OUT/(name+'.json'),{'source':'editorial','asOf':asof,'retrieved':'2026-10-14','note':note,'kinds':{'history':{'label':'Selected historical event','color':'c3'},'architecture':{'label':'Construction period endpoint','color':'c4'},'politics':{'label':'National political decision','color':'c1'},'people':{'label':'People and communities','color':'c4'}},'items':items})
 write(ROOT/'stories'/ (id+'.json'),{'id':id,'cat':'People','title':title,'hook':hook,'updated':'2026-10-14','sources':['editorial'],'notes':note,'data':data,'scenes':scenes})
def cards(kind='history',year=None):
 return [{'type':'cards','data':'events','year':year,'kinds':[kind],'list':True,'labels':False}]

anat=[
 scene('Before states called Turkey','Göbekli Tepe stands in Upper Mesopotamia, near today’s Şanlıurfa. UNESCO dates its monumental enclosures to the tenth and ninth millennia BC and associates their builders with hunter-gatherer communities. This is a place in the history of the land, thousands of years before the Turkish republic.',[38.92,37.22],7,[point('Göbekli Tepe',[38.922,37.223])]),
 scene('A Bronze Age centre inland','Hattusha was the Hittite capital. UNESCO describes its influence across Anatolia and northern Syria in the second millennium BC. Its inland setting contrasts with the Aegean coastal cities in the next scene; the dot marks the archaeological site, not the empire’s borders.',[34.61,40.02],6,[point('Hattusha',[34.615,40.019])]),
 scene('Greek and Roman layers on the Aegean','Ephesus preserves successive Hellenistic and Roman settlements beside an estuary whose coastline changed. The Library of Celsus and Great Theatre belong to its Roman imperial landscape. The archaeological-site marker is inland today; it does not reconstruct the ancient shoreline.',[27.34,37.94],7,[point('Ephesus',[27.342,37.94])]),
 scene('Byzantine Constantinople','At the meeting of the Bosporus and the Sea of Marmara, Constantinople became an imperial centre. UNESCO’s Istanbul heritage account identifies surviving Byzantine works, including Justinian’s Hagia Sophia. Marking that church locates one surviving layer; it does not turn Byzantine history into a history of the modern nation-state.',[28.98,41.01],7,[point('Hagia Sophia',[28.98,41.008])]),
 scene('Armenian Ani at a crossroads','Ani flourished as a capital of the medieval Armenian Bagratid kingdom in the tenth and eleventh centuries. UNESCO describes its later Byzantine, Seljuk and Georgian layers and its caravan connections. Near today’s Armenia–Turkey boundary, the site makes a history of Anatolia broader than the succession of states in Istanbul.',[43.57,40.51],6,[point('Ani',[43.573,40.507])]),
 scene('Seljuk Konya, before Ottoman Bursa','Türkiye’s UNESCO tentative-list description identifies Konya as a Seljuk capital in the twelfth and thirteenth centuries. Farther northwest, Bursa became an early Ottoman capital. These separate centres locate successive political worlds; they are not ethnic territories or a smooth, inevitable transition to modern Turkey.',[31.2,39.2],5,[point('Konya',[32.49,37.87]),point('Bursa')])]
anatrefs=[U+'1572/',U+'377/',U+'1018/',U+'356/',U+'1518/','https://whc.unesco.org/en/tentativelists/1404/',U+'1452/']
build('tr-anatolia','Anatolia before the Ottomans','Archaeological places reveal several histories of the same land.',anat,[],[f'Scene {i+1}: '+u for i,u in enumerate(anatrefs[:6])]+['Scene 6 (Bursa): '+anatrefs[6]],'1300')

ott=[
 scene('A capital and its hinterland','Bursa and nearby Cumalıkızık preserve the urban and rural setting of an early Ottoman capital. UNESCO treats the city and village together: the dynasty’s centre depended on a surrounding landscape, rather than an isolated palace.',[29.06,40.19],7,[point('Bursa'),point('Cumalıkızık',[29.17,40.18])]),
 scene('Constantinople changes hands','The Ottomans captured Constantinople in 1453. The Met describes Mehmed II’s rebuilding programme and Hagia Sophia’s conversion into an imperial mosque. The city’s position joins the Black Sea approach and the Mediterranean world; the marker is a locator, not a siege reconstruction.',[28.98,41.01],6,[point('Constantinople / Istanbul',LOC['Istanbul'])],layers=cards(year=1453)),
 scene('An empire beyond Anatolia','Selim I’s expansion added Mamluk Syria and Egypt to Ottoman rule. Cairo joins Istanbul on this map as a centre of an imperial world spanning several regions. The paired locations convey expansion without claiming precise sixteenth-century borders.',[32.5,35.5],4,[point('Istanbul'),point('Cairo')]),
 scene('Production in several cities','The Met identifies Iznik with ceramics, Bursa with silks, Cairo with carpets and Baghdad with book arts. These centres show the empire’s cultural geography extending beyond its capital. Equal-sized dots mark places, not a ranking of production.',[36,35],4,[point('Iznik'),point('Bursa'),point('Cairo'),point('Baghdad')]),
 scene('Sinan’s architecture across two capitals','Sinan designed Istanbul’s Süleymaniye complex in 1550–1557 and Edirne’s Selimiye in 1568–1574. Locate the two commissions on the timeline. Their separation shows patronage outside the imperial capital; dates refer to construction periods, not exact inauguration days.',[27.8,41.2],6,[point('Istanbul'),point('Edirne')],layers=cards(year='t'),timeline={'years':[1550,1557,1568,1574],'start':1550}),
 scene('A layered inheritance','The Met describes Ottoman art drawing on Byzantine, Persian and Mamluk traditions. Istanbul’s surviving Byzantine and Ottoman monuments make that layering visible in one city. Selected sites cannot show every community or province; the following chapter turns to institutions and the empire’s later pressures.',[28.98,41.01],7,[point('Hagia Sophia',[28.98,41.008]),point('Süleymaniye',[28.964,41.016])])]
items=[event('Constantinople taken',1453,LOC['Istanbul'],'The Ottoman conquest made former Byzantine Constantinople the imperial capital.',MET),event('Süleymaniye construction begins',1550,[28.964,41.016],'The Met dates the Istanbul mosque complex to 1550–1557.',SUL,'architecture'),event('Süleymaniye construction period ends',1557,[28.964,41.016],'End of the construction period given by the Met.',SUL,'architecture'),event('Selimiye construction begins',1568,[26.559,41.678],'The Met dates Sinan’s Edirne commission to 1568–1574.',SUL,'architecture'),event('Selimiye construction period ends',1574,[26.559,41.678],'End of the construction period given by the Met.',SUL,'architecture')]
ott[4]['layers']=cards('architecture','t')
build('tr-ottoman-world','An Ottoman world','Capital cities, provincial production and surviving architecture connect a wider empire.',ott,items,['Scene 1: '+U+'1452/','Scenes 2-4,6: '+MET,'Scene 5: '+SUL,'Scene 6 (surviving monuments): '+U+'356/'],'1574')

# Preserve the cached provider metadata, observation years and definition caveat.
urban=json.loads((ROOT/'data/atlas/SP.URB.TOTL.IN.ZS.json').read_text(encoding='utf-8'))
urban['series']['v']['values']={'TUR':urban['series']['v']['values']['TUR']}
urban['note']+=' Orbis subset: Turkey only. National urban definitions change; this is not a constant built-up-area measure or city-level series. 2025 UN WUP revision is retained as cached; compare only within this release.'
write(OUT/'urban.json',urban)
chg=[
 scene('Political power in Ankara','The parliament’s history records the military coup of 27 May 1960, the arrest of the prime minister and other leaders, and the suspension of the Assembly. The capital locator marks national institutions; it does not imply that the consequences were confined to Ankara.',LOC['Ankara'],6,[point('Ankara')],layers=cards('politics',1960)),
 scene('Interventions and constitutions','The parliament describes the military memorandum of 1971 and the coup of September 1980. The timeline locates these national turning points in Ankara. Events appear cumulatively; a point represents the decision-making centre, not a map of political support or violence.',LOC['Ankara'],6,[point('Ankara')],layers=cards('politics','t'),timeline={'years':[1960,1971,1980],'start':1960}),
 scene('A country becomes more urban','The cached World Bank urban-share series rises from about 23% in 1960 to 89% in 2024 under its national definitions. The line shows the national series; Istanbul, Ankara and İzmir locate major cities discussed in the World Bank urbanization review. The dots do not contain city populations.',[31.2,39.8],5,[point('Istanbul'),point('Ankara'),point('Izmir')],media={'type':'line','data':'urban','series':'v','countries':['TUR'],'title':'Turkey: urban share, national definitions','fmt':'pct'},layers=[{'type':'choropleth','data':'urban','series':'v','year':'t','vmin':0,'vmax':100,'fmt':'pct','title':'Urban share (%)'}],timeline={'years':[1960,2024],'start':1960},modernBorders=True),
 scene('Labour migration beyond the border','The 1961 recruitment agreement enabled regulated labour migration from Turkey to West Germany. Bonn locates the German agreement’s political setting, and Istanbul locates Turkey schematically. These dots are country-side reference points, not a claim that migrants all followed one route or came from one city.',[21,46],3,[point('Istanbul'),point('Bonn')]),
 scene('Kurdish communities and conflict in the southeast','OHCHR’s March 2017 report describes destruction, displacement and alleged human-rights violations in predominantly Kurdish southeastern towns during July 2015–December 2016, including Diyarbakır and Nusaybin. These are selected reported places, not an ethnic boundary, casualty surface or current conflict map. Its findings concern that specific window.',[40.7,37.7],6,[point('Diyarbakir'),point('Nusaybin')]),
 scene('A different executive system','The 2017 constitutional amendments changed the republic from a parliamentary to a presidential system. OSCE’s report on the 2018 elections describes implementation of that change. Ankara remains the institutional centre on this map; no regional voting pattern can be inferred from that single point.',LOC['Ankara'],6,[point('Ankara')]),
 scene('Earthquakes across a national boundary','On 6 February 2023, USGS recorded a magnitude 7.8 earthquake near the Syria–Turkey border. Its epicentre lies near the southeastern cities already discussed. The point marks the USGS epicentre; the city dots provide context, without asserting a damage footprint or a casualty estimate.',[37.2,37.5],6,[point('M7.8 epicentre',[37.032,37.226],'c2'),point('Gaziantep'),point('Aleppo')])]
chgitems=[event('Military coup',1960,LOC['Ankara'],'On 27 May 1960 the military suspended the Assembly and arrested national leaders.',PAR,'politics'),event('Military memorandum',1971,LOC['Ankara'],'The 12 March 1971 memorandum preceded extensive changes to the 1961 constitution.',PAR,'politics'),event('Military coup',1980,LOC['Ankara'],'The 12 September 1980 coup interrupted parliamentary government.',PAR,'politics')]
chg[2]['media']=[chg[2]['media']]
build('tr-changing-republic','A changing republic','Urban growth, political interventions, migration and unequal regional experiences.',chg,chgitems,['Scenes 1-2: '+PAR,'Scene 3 (cities): '+WB,'Scene 3 (urban series): https://data.worldbank.org/indicator/SP.URB.TOTL.IN.ZS?locations=TR','Scene 4: '+GER,'Scene 5: '+OHCHR+' ; corroborating UN library report https://unric.org/en/wp-content/uploads/sites/15/2018/12/libnews-march2017.pdf','Scene 6: https://cdn.osce.org/sites/default/files/f/documents/9/4/397046_0.pdf','Scene 7: '+QUAKE],'2025',{'urban':'data/history/turkey/urban.json'})

world=[
 scene('The straits join two seas','The Bosporus and Dardanelles connect the Black Sea through the Sea of Marmara to the Aegean. The 1936 Montreux Convention regulates passage through the straits. The markers locate those passages; they are not shipping-volume observations or a reconstructed vessel route.',[28,40.6],6,[point('Bosporus',[29.06,41.15]),point('Dardanelles',[26.42,40.15])]),
 scene('NATO’s southeastern flank','Turkey and Greece joined NATO in February 1952. NATO’s history describes Turkey’s strategic position and land and sea bases as important to the alliance. The two country outlines identify the new members in present-day geometry; they do not reconstruct Cold War deployments.',[27,39],4,[point('Ankara')],modernBorders=True,highlight=['TUR','GRC'],fills={'TUR':'c1','GRC':'c1'}),
 scene('Cyprus: intervention and division','UNFICYP records a Greek-officer-directed coup on 15 July 1974 and Turkish landings on 20 July. In 1983 the Security Council declared the northern secession legally invalid. Nicosia locates the divided island; this map draws no occupation boundary and does not settle competing political claims.',[33.36,35.17],7,[point('Nicosia')],layers=cards('history','t'),timeline={'years':[19740715,19740720,19831118],'format':'date','start':19740715}),
 scene('Work and family ties with Europe','The 1961 recruitment agreement connected Turkey with West Germany through labour migration. Marking Bonn and Istanbul shows the international relationship’s geographic span. It represents neither every migrant’s origin nor present-day diaspora size; migration is part of international history as well as domestic change.',[21,46],3,[point('Bonn'),point('Istanbul')]),
 scene('An EU relationship with several stages','The Council of the EU records candidate status in 1999, the opening of accession talks in 2005 and their effective standstill in June 2018. Brussels and Ankara locate the institutional relationship. The dated cards explain the sequence; candidate status is not EU membership.',[20,46],3,[point('Brussels'),point('Ankara')],layers=cards('politics','t'),timeline={'years':[1999,2005,2018],'start':1999}),
 scene('Syria: refuge and return','UNHCR’s 8 December 2025 account describes growing demand for voluntary return from Syria’s neighbouring host countries. Turkey’s southern border is part of that regional displacement geography. Aleppo and Gaziantep are reference locations, not observed individual journeys. This dated source does not establish conditions or totals on 14 October 2026.',[37.3,36.65],6,[point('Aleppo'),point('Gaziantep')])]
worlditems=[event('Coup against the Cyprus government',19740715,LOC['Nicosia'],'UNFICYP describes the National Guard coup under the direction of Greek officers.',CY),event('Turkish forces land',19740720,[33.32,35.33],'UNFICYP records Turkish landings on the northern coast of Cyprus.',CY),event('Security Council resolution 541',19831118,LOC['Nicosia'],'The Security Council considered the northern declaration of secession legally invalid and called for its withdrawal. Nicosia is an island locator, not the adoption site.', 'https://digitallibrary.un.org/record/58970?v=pdf'),event('EU candidate status',1999,LOC['Ankara'],'The Helsinki European Council granted Turkey candidate status in December 1999. Ankara is the candidate country’s capital, not the meeting site.',EU,'politics'),event('EU accession negotiations',2005,LOC['Brussels'],'Accession negotiations opened on 3 October 2005.',EU,'politics'),event('Negotiations at a standstill',2018,LOC['Brussels'],'The Council described negotiations as effectively at a standstill in June 2018.',EU,'politics')]
build('tr-world','Turkey in the world','Straits, alliances, Cyprus, Europe and Syria in a dated regional history.',world,worlditems,['Scenes 1-2: '+NATO,'Scene 3 (1974): '+CY,'Scene 3 (1983): https://digitallibrary.un.org/record/58970?v=pdf','Scene 4: '+GER,'Scene 5: '+EU,'Scene 6: '+RET],'2025-12-08')
print('Built four chapters and five small datasets; no shared registry files changed.')
